"""Vendored patches replay idempotently and checkouts keep generated bytes."""
import subprocess
import tempfile
import unittest
from pathlib import Path
from unittest import mock

import apply_patches
import gen_exports


class VendoredPatchTests(unittest.TestCase):
    def test_every_patch_targets_the_vendored_tree(self):
        listed = set(apply_patches.PATCHES)
        on_disk = {p.stem for p in apply_patches.PATCH_DIR.glob("*.patch")}
        self.assertEqual(listed, on_disk)
        for name in sorted(listed):
            text = (apply_patches.PATCH_DIR / (name + ".patch")).read_text(
                encoding="utf-8")
            for line in text.splitlines():
                if line.startswith("+++ b/"):
                    with self.subTest(patch=name):
                        self.assertTrue(line[6:].startswith("upstream/boost/"),
                                        line)

    def test_applied_patch_is_skipped_with_git(self):
        name = "io"
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            (root / "patches").mkdir()
            patch = apply_patches.PATCH_DIR / (name + ".patch")
            (root / "patches" / patch.name).write_bytes(patch.read_bytes())
            for line in patch.read_text(encoding="utf-8").splitlines():
                if line.startswith("+++ b/"):
                    rel = line[6:]
                    dst = root / rel
                    dst.parent.mkdir(parents=True, exist_ok=True)
                    dst.write_bytes((apply_patches.ROOT / rel).read_bytes())
            before = {p: p.read_bytes() for p in root.rglob("*.hpp")}
            with mock.patch.object(apply_patches, "ROOT", root), \
                    mock.patch("subprocess.run", wraps=subprocess.run) as run:
                apply_patches.apply_patch_file(name)
            self.assertEqual({p: p.read_bytes() for p in before}, before)
            self.assertTrue(all(call.args[0][0] == "git"
                                for call in run.call_args_list))


    def test_missing_git_falls_back_to_patch(self):
        real = subprocess.run

        def no_git(cmd, *a, **kw):
            if cmd[0] == "git":
                raise FileNotFoundError(2, "No such file", "git")
            return real(cmd, *a, **kw)

        calls = []
        ok = subprocess.CompletedProcess([], 0, "", "")

        def fake(cmd, *a, **kw):
            calls.append(list(cmd))
            if cmd[0] == "git":
                return no_git(cmd, *a, **kw)
            return ok

        with mock.patch("subprocess.run", side_effect=fake):
            apply_patches.apply_patch_file("io")
        self.assertEqual([c[0] for c in calls],
                         ["git", "git", "patch", "patch"])
        self.assertNotIn("--dry-run", calls[-1])

    def test_failure_reports_both_tools(self):
        def fail(cmd, *a, **kw):
            if cmd[0] == "git":
                raise FileNotFoundError(2, "No such file", "git")
            return subprocess.CompletedProcess(cmd, 1, "", "hunk FAILED")

        with mock.patch("subprocess.run", side_effect=fail), \
                self.assertRaises(SystemExit) as cm:
            apply_patches.apply_patch_file("io")
        self.assertIn("No such file", str(cm.exception))
        self.assertIn("hunk FAILED", str(cm.exception))

class CheckoutTests(unittest.TestCase):
    def test_windows_checkout_preserves_generation_bytes(self):
        # Exercise Git's actual Windows-style checkout conversion on every OS.
        paths = (
            "patches/io.patch", "src/winapi.cppm",
            "generated/exports/winapi.inc", "generated/exports/system.deps",
            "generated/meta/skipped.txt", "tools/export_policy.toml",
        )
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)

            def git(*args):
                return subprocess.run(
                    ["git", "-c", "core.autocrlf=true", *args], cwd=root,
                    capture_output=True, check=True)

            git("init")
            (root / ".gitattributes").write_bytes(
                (gen_exports.bc.ROOT / ".gitattributes").read_bytes())
            for rel in paths:
                dst = root / rel
                dst.parent.mkdir(parents=True, exist_ok=True)
                dst.write_bytes((gen_exports.bc.ROOT / rel).read_bytes())
            git("add", ".")
            for rel in paths:
                (root / rel).unlink()
            git("checkout-index", "--all", "--force")
            for rel in paths:
                with self.subTest(path=rel):
                    self.assertEqual((root / rel).read_bytes(),
                                     (gen_exports.bc.ROOT / rel).read_bytes())


if __name__ == "__main__":
    unittest.main()
